import re
def clean(s):
    out=[]
    for n in s.split('、'):
        n=n.strip()
        n=re.sub(r'（[^）]*）|\([^)]*\)','',n) if not re.match(r'^[A-Za-z]',n) else n
        n=re.sub(r'株式会社|\bINC\.?$|,? ?Inc\.?$|PTE\. LTD\.|CO\.,? ?LTD\.?|CORP\.?$|\s+','' if False else '',n) if False else n
        n=n.replace('株式会社','').replace('ホールディングス','HD').strip(' ,')
        if n: out.append(n)
    return ', '.join(dict.fromkeys(out))
